"use client";

import { useSortable } from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";

export default function TaskItem({ id, columnId, text }: any) {
  const { setNodeRef, attributes, listeners, transform, transition } =
    useSortable({
      id,
      data: { column: columnId },
    });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
  };

  return (
    <div
      ref={setNodeRef}
      style={style}
      {...attributes}
      {...listeners}
      className="p-3 bg-white text-black rounded-lg shadow hover:scale-[1.02] transition cursor-grab"
    >
      {text}
    </div>
  );
}