"use client";

import { useState } from "react";
import {
  SortableContext,
  verticalListSortingStrategy,
} from "@dnd-kit/sortable";
import TaskItem from "./TaskItem";

export default function ScrumColumn({ id, title, items, setColumns }: any) {
  const [showForm, setShowForm] = useState(false);
  const [input, setInput] = useState("");

  const addTask = () => {
    if (!input.trim()) return;

    setColumns((prev: any) => ({
      ...prev,
      [id]: [...prev[id], input],
    }));

    setInput("");
    setShowForm(false);
  };

  return (
    <>
      <div className="bg-white/10 backdrop-blur-lg p-4 rounded-xl shadow-lg w-[280px] border border-white/10">
        <h2 className="text-lg font-semibold mb-4 text-white">
          {title}
        </h2>

        {/* SORTABLE TASKS */}
        <SortableContext
          items={items}
          strategy={verticalListSortingStrategy}
        >
          <div className="flex flex-col gap-3">
            {items.map((item) => (
              <TaskItem
                key={item}
                id={item}
                columnId={id}
                text={item}
              />
            ))}
          </div>
        </SortableContext>

        <button
          onClick={() => setShowForm(true)}
          className="w-full mt-4 py-2 bg-white/10 text-white rounded-lg hover:bg-blue-600 transition"
        >
          + Taak toevoegen
        </button>
      </div>

      {/* ADD TASK MODAL */}
      {showForm && (
        <div className="fixed inset-0 z-50 flex items-center justify-center">
          <div
            className="absolute inset-0 bg-black/50 backdrop-blur-sm"
            onClick={() => setShowForm(false)}
          />

          <div className="relative bg-white p-6 rounded-2xl shadow-2xl w-[380px] animate-[fadeIn_0.2s_ease]">
            <h3 className="text-lg font-semibold mb-3 text-black">
              Nieuwe taak
            </h3>

            <textarea
              className="w-full p-3 border rounded-lg text-black h-28"
              placeholder="Schrijf je taak..."
              value={input}
              onChange={(e) => setInput(e.target.value)}
              autoFocus
            />

            <div className="flex justify-end gap-2 mt-4">
              <button
                onClick={() => setShowForm(false)}
                className="px-4 py-2 bg-gray-200 rounded-lg hover:bg-gray-300"
              >
                Annuleren
              </button>
              <button
                onClick={addTask}
                className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
              >
                Toevoegen
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  );
}